<template><view class="page page-wide"><PageHeader title="贡献" subtitle="记录每一次掌勺与点菜"/><view v-if="loading&&!members.length" class="state">正在加载贡献记录...</view><view v-else-if="error&&!members.length" class="state panel"><text>{{error}}</text><button class="btn tonal" @tap="load">重试</button></view><view v-else-if="!members.length" class="state">完成第一场饭局后，这里会出现记录</view><view v-else class="members"><view v-for="member in members" :key="member.id" class="member"><view class="member-head"><Avatar :name="member.name" :src="assetUrl(member.avatar_path)" :size="82"/><view class="member-meta"><text class="name">{{member.name}}</text><view class="totals"><text>做饭 {{member.cook_total||0}} 次</text><text>点菜 {{member.order_total||0}} 次</text><text v-if="member.streak">连续 {{member.streak}} 天</text></view></view></view><view class="heat"><text class="heat-label">做饭记录</text><view class="squares"><view v-for="(level,index) in heatClasses(member.cook_by_date,start)" :key="'c'+index" class="square" :class="level"/></view></view></view><view v-if="error" class="state panel"><text>{{error}}</text><button class="btn tonal" @tap="load">重试</button></view></view><AppTabBar active="wall"/></view></template>
<script setup lang="js">
import { onActivated,onMounted,ref } from 'vue';import AppTabBar from '../../components/AppTabBar.vue';import PageHeader from '../../components/PageHeader.vue';import Avatar from '../../components/Avatar.vue';import {assetUrl,request} from '../../api/client';import {heatmapDateKey} from '../../utils/app'
const members=ref([]),start=ref(''),loading=ref(false),error=ref('')
function heatClasses(data,startDate){const result=[];for(let index=0;index<112;index+=1){let key='';try{key=heatmapDateKey(startDate,index)}catch{}const count=key&&data&&typeof data==='object'?Number(data[key])||0:0;result.push(count?`l${Math.min(count,4)}`:'')}return result}
async function load(){if(loading.value)return;loading.value=true;error.value='';try{const data=await request('/api/contributions');members.value=Array.isArray(data?.members)?data.members:[];start.value=typeof data?.start==='string'?data.start:''}catch(loadError){error.value=loadError?.message||'贡献记录加载失败'}finally{loading.value=false}}onMounted(load);onActivated(load)
</script>
<style scoped>.members{display:grid;grid-template-columns:minmax(0,1fr);gap:34rpx}.member{padding:34rpx 24rpx;border-top:1px solid var(--theme-border-subtle)}.member-head{display:flex;align-items:center}.member-meta{display:flex;min-width:0;margin-left:20rpx;flex:1;flex-direction:column}.name{font-size:31rpx;font-weight:650}.totals{display:flex;margin-top:4rpx;flex-wrap:wrap;gap:6rpx 18rpx;color:var(--theme-text-secondary);font-size:22rpx}.heat{margin-top:26rpx}.heat-label{display:block;margin-bottom:10rpx;color:var(--theme-text-tertiary);font-size:23rpx}.squares{display:grid;width:100%;grid-template-columns:repeat(16,minmax(0,1fr));gap:4rpx}.square{width:100%;aspect-ratio:1;border-radius:3rpx;background:var(--theme-heat-0)}.square.l1{background:var(--theme-heat-1)}.square.l2{background:var(--theme-heat-2)}.square.l3{background:var(--theme-heat-3)}.square.l4{background:var(--theme-heat-4)}.state .btn{margin-top:18rpx}@media(min-width:900px){.members{grid-template-columns:repeat(2,minmax(0,1fr));gap:32rpx}.member{padding:32rpx;border:1px solid var(--theme-border-subtle);border-radius:var(--radius-panel);background:var(--theme-bg-surface)}}</style>
